<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue';import {api} from '../api';import type {ScanResult,SDKSessionEvent} from '../contracts';import {sdkSessionView} from '../utils/sdk-operations';import Button from './ui/Button.vue';
const props=defineProps<{scanId:number;attempt:number;result?:ScanResult}>();
const summary=computed(()=>props.result?sdkSessionView(props.result.extensions?.sdkSession,props.result.execution,props.result.artifacts):null);
const partial=ref(''),captured=ref(0);const execution=computed(()=>props.result?.execution??{taskId:String(props.scanId),attempt:props.attempt});
const items=ref<SDKSessionEvent[]>([]),selected=ref<SDKSessionEvent>(),busy=ref(false),error=ref(''),loaded=ref(false),next=ref(0),more=ref(false),cursors=ref<number[]>([]),cursor=ref(0),downloading=ref(false);let generation=0;
watch(()=>[props.scanId,props.attempt,props.result],()=>{generation++;partial.value='';captured.value=0;items.value=[];selected.value=undefined;loaded.value=false;error.value='';busy.value=false;downloading.value=false;cursors.value=[];cursor.value=0;},{immediate:true});onUnmounted(()=>generation++);
async function load(after=0){const gen=++generation;busy.value=true;error.value='';try{const page=await api.sdkSessions(props.scanId,props.attempt,after);if(gen!==generation)return;const identity=page.summary?.execution??page.execution;if(!identity||identity.taskId!==execution.value.taskId||identity.attempt!==props.attempt||page.items.some((e,i)=>e.execution.taskId!==execution.value.taskId||e.execution.attempt!==props.attempt||e.sequence<=after||(i>0&&e.sequence!==page.items[i-1]!.sequence+1)))throw new Error('会话事件的执行身份或顺序不匹配');partial.value=page.uncommitted?page.reason??'未提交日志，完整性未知':'';captured.value=page.capturedCount??0;items.value=page.items;next.value=page.next;more.value=page.hasMore;cursor.value=after;selected.value=undefined;loaded.value=true;}catch(e){if(gen===generation)error.value='原生会话事件读取失败：'+(e as Error).message;}finally{if(gen===generation)busy.value=false;}}
async function forward(){const previous=cursor.value;await load(next.value);if(!error.value)cursors.value.push(previous);}
async function back(){const previous=cursors.value.at(-1);if(previous===undefined)return;await load(previous);if(!error.value)cursors.value.pop();}
async function download(){const gen=generation,ref=summary.value?.journal;if((!ref&&props.result)||downloading.value)return;downloading.value=true;error.value='';try{const blob=ref?await api.resultArtifact(props.scanId,props.attempt,ref.relativePath):await api.uncommittedSDKSessions(props.scanId,props.attempt);if(gen!==generation)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=ref?'sdk-session-events.jsonl':'sdk-session-events.partial.jsonl';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){if(gen===generation)error.value='会话事件下载失败：'+(e as Error).message;}finally{if(gen===generation)downloading.value=false;}}
function type(e:SDKSessionEvent){const raw=e.event.event;return raw&&typeof raw==='object'&&!Array.isArray(raw)?String(raw.type??'unknown'):'unknown';}
</script>
<template>
 <section aria-label="SDK 原生会话事件" class="sdk-sessions"><header><h3>SDK 原生会话事件</h3><template v-if="summary||!result"><Button size="sm" variant="outline" :loading="busy" @click="load(cursor)">{{loaded?'重新读取会话事件':'查看原生会话事件'}}</Button><Button v-if="summary?.journal||!result" size="sm" variant="ghost" :loading="downloading" @click="download">下载完整会话 JSONL</Button></template></header>
  <p v-if="result&&!summary">{{result.extensions?.sdkSession===undefined?'此历史执行未记录完整原生会话事件；原有活动和日志继续可读。':'会话事件扩展的版本、身份或产物引用不受支持，完整归档仍可访问。'}}</p>
  <p v-if="!result">{{partial||'执行尚未提交完整 SDK 结果，可读取已保存事件，总事件数与完整性未知。'}}<template v-if="loaded"> 已核验 {{captured}} 条完整记录。</template></p>
  <template v-if="summary||!result"><p v-if="summary">收到 {{summary.receivedCount}} 条 · 保存 {{summary.persistedCount}} 条 · 缺失 {{summary.omittedCount}} 条。保留全部回调类型；展示内容已脱敏。</p><p v-if="summary?.reason" role="alert" class="request-error">{{summary?.reason}}</p><p v-if="summary&&!summary.receivedCount">SDK 本次未提供会话事件，不能据此推断内部没有活动。</p>
   <div v-if="items.length" class="event-table"><table><thead><tr><th>序号</th><th>Thread / Worker</th><th>原生事件类型</th><th>发生时间</th></tr></thead><tbody><tr v-for="item in items" :key="item.sequence" :class="{selected:selected?.sequence===item.sequence}"><td><button type="button" :aria-pressed="selected?.sequence===item.sequence" @click="selected=item">查看事件 {{item.sequence}}</button></td><td>{{item.threadId}} / {{item.worker??'未提供'}}</td><td>{{type(item)}}</td><td>{{item.occurredAt}}</td></tr></tbody></table></div>
   <nav v-if="loaded" aria-label="会话事件分页"><Button size="sm" variant="outline" :disabled="busy||!cursors.length" @click="back">上一页会话事件</Button><span>{{items.length?'序号 '+items[0]!.sequence+'–'+items.at(-1)!.sequence:'当前页没有事件'}}</span><Button size="sm" variant="outline" :disabled="busy||!more" @click="forward">下一页会话事件</Button></nav>
   <aside v-if="selected" aria-label="原生会话事件详情"><header><h4>事件 {{selected.sequence}} · {{selected.threadId}}</h4><Button size="sm" variant="ghost" @click="selected=undefined">关闭会话事件详情</Button></header><pre>{{JSON.stringify(selected,null,2)}}</pre></aside>
  </template><p v-if="error" role="alert" class="request-error">{{error}}</p>
 </section>
</template>
<style scoped>
.sdk-sessions{border-top:1px solid var(--border-default);margin-top:var(--space-3);padding-top:var(--space-3);min-width:0;font-size:var(--font-size-xs)}header,nav{display:flex;align-items:center;gap:var(--space-2);flex-wrap:wrap}h3,h4{margin:0;font-size:var(--font-size-sm);font-weight:var(--font-weight-medium)}p{margin:var(--space-2) 0;color:var(--text-secondary);line-height:var(--line-height-body);overflow-wrap:anywhere}.event-table{overflow:auto;max-height:calc(var(--height-table-row)*12)}table{width:100%;border-collapse:collapse;text-align:left}th,td{padding:var(--space-2);border-bottom:1px solid var(--border-subtle);white-space:nowrap}th{color:var(--text-secondary);font-weight:var(--font-weight-medium)}td button{color:var(--accent-primary)}tr.selected{background:var(--surface-selected)}nav{margin:var(--space-2) 0}aside{border-top:1px solid var(--border-subtle);padding-top:var(--space-2)}pre{max-height:calc(var(--height-table-row)*10);overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;background:var(--surface-secondary);padding:var(--space-2);font:var(--font-size-xs)/var(--line-height-body) var(--font-mono)}
</style>
